CREATE TABLE "gxp_audit_event" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL,
    "ledger_sequence" bigint NOT NULL,
    "operation_id" varchar(128) NOT NULL,
    "domain" varchar(64) NOT NULL,
    "subject_type" varchar(64) NOT NULL,
    "subject_id" varchar(2048) NOT NULL,
    "subject_version" varchar(128) NOT NULL,
    "action" varchar(64) NOT NULL,
    "reason" varchar(2000) NOT NULL,
    "actor_id" bigint NOT NULL,
    "actor_username" varchar(64) NOT NULL,
    "actor_display_name" varchar(128) NOT NULL,
    "server_occurred_at" timestamp(3) NOT NULL,
    "before_state" varchar(32) NOT NULL,
    "before_object_version" varchar(128),
    "before_state_json" clob,
    "after_state" varchar(32) NOT NULL,
    "after_object_version" varchar(128),
    "after_state_json" clob,
    "policy_version" varchar(128) NOT NULL,
    "idempotency_key" varchar(512) NOT NULL,
    "request_id" varchar(128),
    "signature_record_id" varchar(128),
    "signature_content_hash" varchar(128),
    "idempotency_payload_hash" varchar(64) NOT NULL,
    "canonical_event_json" clob NOT NULL,
    "previous_event_hash" varchar(64),
    "event_hash" varchar(64) NOT NULL,
    "algorithm" varchar(32) NOT NULL,
    "event_schema_version" smallint,
    "canonicalization_version" varchar(32),
    "result_status" varchar(16),
    "reason_code" varchar(64),
    "reason_source" varchar(16),
    "transaction_id" varchar(64),
    "authenticated_actor_json" clob,
    "performed_by_json" clob,
    "source_type" varchar(64),
    "source_locator" varchar(512),
    "trace_id" varchar(128),
    "error_code" varchar(128),
    "attempted_operation_id" varchar(128),
    "relation_manifest_json" clob,
    "evidence_manifest_json" clob,
    "state_payload_hash" varchar(64),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "ledger_sequence"),
    UNIQUE ("tenant_id", "idempotency_key")
) COMMENT 'GxP 统一审计事件只追加账本';

CREATE TABLE "gxp_audit_ledger_sequence" (
    "tenant_id" bigint NOT NULL,
    "next_ledger_sequence" bigint NOT NULL,
    "create_time" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_time" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("tenant_id")
) COMMENT 'GxP 审计账本序号水位';

CREATE TABLE "gxp_audit_policy_operation" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL,
    "policy_version" varchar(128) NOT NULL,
    "operation_id" varchar(128) NOT NULL,
    "source_type" varchar(64) NOT NULL,
    "source_locator" varchar(512) NOT NULL,
    "domain" varchar(64) NOT NULL,
    "subject_type" varchar(64) NOT NULL,
    "action_type" varchar(64) NOT NULL,
    "reason_policy" varchar(64) NOT NULL,
    "signature_policy" varchar(64) NOT NULL,
    "state_policy" varchar(64) NOT NULL,
    "retention_class" varchar(64) NOT NULL,
    "test_ids" varchar(512) NOT NULL,
    "owner" varchar(128) NOT NULL,
    "applicability" varchar(64) NOT NULL,
    "active" bit NOT NULL DEFAULT TRUE,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "operation_id", "policy_version")
) COMMENT 'GxP 审计策略操作登记';

CREATE TABLE "gxp_audit_event_relation" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL,
    "event_id" bigint NOT NULL,
    "relation_type" varchar(32) NOT NULL,
    "target_type" varchar(64) NOT NULL,
    "target_id" varchar(128) NOT NULL,
    "target_version" varchar(128),
    "target_hash" varchar(64),
    "created_at_utc" timestamp(3) NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "event_id", "relation_type", "target_type", "target_id")
) COMMENT 'GxP 审计事件规范关联索引';

CREATE TABLE "gxp_audit_policy_activation" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL,
    "policy_version" varchar(128) NOT NULL,
    "policy_hash" varchar(64) NOT NULL,
    "previous_activation_hash" varchar(64),
    "request_id" varchar(128) NOT NULL,
    "actor_id" bigint NOT NULL,
    "approval_reference" varchar(256) NOT NULL,
    "activated_at_utc" timestamp(3) NOT NULL,
    "effective_after_sequence" bigint NOT NULL,
    "canonical_activation_json" clob NOT NULL,
    "activation_hash" varchar(64) NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "request_id"),
    UNIQUE ("tenant_id", "activation_hash")
) COMMENT 'GxP 审计策略激活历史';

CREATE TABLE mes_independent_batch_prerequisite_receipt (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  receipt_id varchar(64) NOT NULL,
  tenant_id bigint NOT NULL,
  entry_type varchar(32) NOT NULL,
  work_order_id bigint NOT NULL,
  work_order_code varchar(64) NOT NULL,
  route_id bigint NOT NULL,
  route_version_id bigint NOT NULL,
  route_version varchar(64) NOT NULL,
  batch_code varchar(128) NOT NULL,
  source_relation_id varchar(128) NOT NULL,
  source_relation_version varchar(64) NOT NULL,
  source_relation_snapshot_hash char(64) NOT NULL,
  source_object_type varchar(64) NOT NULL,
  source_object_id varchar(128) NOT NULL,
  material_source_type varchar(64) NOT NULL,
  material_source_id varchar(128) NOT NULL,
  source_context_hash char(64) NOT NULL,
  source_snapshot_hash char(64) NOT NULL,
  business_reason varchar(512) NOT NULL,
  issuer_system varchar(128) NOT NULL,
  issuer_user_id bigint NOT NULL,
  issuer_user_role varchar(128) NOT NULL,
  issued_at timestamp(0) NOT NULL,
  expires_at timestamp(0) NOT NULL,
  revoked_at timestamp(0) DEFAULT NULL,
  revocation_reason varchar(512) DEFAULT NULL,
  credential_version bigint NOT NULL,
  status varchar(16) NOT NULL,
  canonical_payload clob NOT NULL,
  source_evidence_json clob NOT NULL,
  receipt_hash char(64) NOT NULL,
  payload_hash char(64) NOT NULL,
  signature char(64) NOT NULL,
  audit_event_id varchar(128) NOT NULL,
  idempotency_key varchar(128) NOT NULL,
  creator varchar(64) DEFAULT '',
  create_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updater varchar(64) DEFAULT '',
  update_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted boolean NOT NULL DEFAULT FALSE,
  PRIMARY KEY (id),
  CONSTRAINT uk_independent_receipt_tenant_receipt UNIQUE (tenant_id, receipt_id, deleted),
  CONSTRAINT uk_independent_receipt_tenant_idempotency UNIQUE (tenant_id, entry_type, idempotency_key, deleted)
);

CREATE TABLE mes_pro_edhr_material_gate_receipt (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  receipt_id varchar(128) NOT NULL,
  tenant_id bigint NOT NULL DEFAULT 0,
  batch_execution_id bigint NOT NULL,
  gate_status varchar(32) NOT NULL,
  material_type_keys_json varchar(512) NOT NULL,
  manifest_hash char(64) NOT NULL,
  source_snapshot_hash char(64) NOT NULL,
  material_version_set_hash char(64) NOT NULL,
  receipt_hash char(64) NOT NULL,
  issued_by bigint NOT NULL,
  audit_event_id varchar(128) NOT NULL,
  version int NOT NULL,
  creator varchar(64) DEFAULT '',
  create_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updater varchar(64) DEFAULT '',
  update_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted boolean NOT NULL DEFAULT FALSE,
  PRIMARY KEY (id),
  CONSTRAINT uk_mes_edhr_material_gate_receipt_id UNIQUE (tenant_id, receipt_id, deleted),
  CONSTRAINT uk_mes_edhr_material_gate_receipt_version UNIQUE (tenant_id, batch_execution_id, version, deleted)
);

CREATE TABLE mes_pro_process_pool_active_order_completion_receipt (
    id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    active_order_id bigint NOT NULL,
    work_order_id bigint NOT NULL,
    batch_code varchar(128) NOT NULL,
    route_id bigint NOT NULL,
    route_version_id bigint NOT NULL,
    leader_user_id bigint NOT NULL,
    request_idempotency_key varchar(128) NOT NULL,
    request_payload_hash char(64) NOT NULL,
    source_snapshot_hash char(64) NOT NULL,
    formal_source_snapshot_json clob NOT NULL,
    signature_snapshot_json clob NOT NULL,
    receipt_hash char(64) NOT NULL,
    expected_version int NOT NULL,
    completed_version int NOT NULL,
    receipt_status varchar(32) NOT NULL,
    completion_status varchar(32) DEFAULT NULL,
    batch_record_status varchar(32) NOT NULL,
    process_inspection_status varchar(32) NOT NULL,
    batch_record_id bigint NOT NULL,
    process_inspection_id bigint NOT NULL,
    loss_report_status varchar(32) NOT NULL,
    has_actual_loss boolean NOT NULL,
    loss_quantity decimal(24,6) NOT NULL,
    loss_record_id bigint DEFAULT NULL,
    zero_loss_confirmation_snapshot clob DEFAULT NULL,
    loss_condition_facts_json clob NOT NULL,
    batch_record_source_ids_json clob NOT NULL,
    process_inspection_source_ids_json clob NOT NULL,
    loss_source_hash char(64) DEFAULT NULL,
    provision_handoff varchar(32) NOT NULL,
    completed_at timestamp(0) NOT NULL,
    completed_by bigint NOT NULL,
    creator varchar(64) DEFAULT '',
    create_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '',
    update_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted boolean NOT NULL DEFAULT FALSE,
    tenant_id bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    CONSTRAINT uk_mes_pp_completion_receipt_order UNIQUE (tenant_id, active_order_id, deleted),
    CONSTRAINT uk_mes_pp_completion_receipt_idempotency UNIQUE (tenant_id, request_idempotency_key, deleted)
);

CREATE TABLE mes_edhr_source_creation_binding (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tenant_id bigint NOT NULL,
  owner_protocol varchar(64) NOT NULL,
  source_row_id bigint NOT NULL,
  source_receipt_id varchar(128) NOT NULL,
  source_version varchar(64) NOT NULL,
  source_hash char(64) NOT NULL,
  request_hash_version varchar(32) NOT NULL,
  request_hash char(64) NOT NULL,
  creation_event_id bigint NOT NULL,
  creation_event_hash char(64) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT uk_mes_edhr_creation_row UNIQUE (tenant_id,owner_protocol,source_row_id),
  CONSTRAINT uk_mes_edhr_creation_receipt UNIQUE (tenant_id,owner_protocol,source_receipt_id,source_version),
  CONSTRAINT uk_mes_edhr_creation_event UNIQUE (tenant_id,creation_event_id)
);

CREATE INDEX idx_independent_receipt_source_relation ON mes_independent_batch_prerequisite_receipt(tenant_id,source_relation_id,source_relation_version);
CREATE INDEX idx_independent_receipt_source_snapshot ON mes_independent_batch_prerequisite_receipt(tenant_id,source_snapshot_hash);
CREATE INDEX idx_independent_receipt_status ON mes_independent_batch_prerequisite_receipt(tenant_id,status,expires_at);
CREATE INDEX idx_mes_edhr_material_gate_receipt_batch ON mes_pro_edhr_material_gate_receipt(tenant_id,batch_execution_id,version,deleted);
CREATE INDEX idx_mes_pp_completion_receipt_source_hash ON mes_pro_process_pool_active_order_completion_receipt(tenant_id,source_snapshot_hash);
CREATE INDEX idx_mes_pp_completion_receipt_work_order ON mes_pro_process_pool_active_order_completion_receipt(tenant_id,work_order_id);

CREATE TABLE dcc_electronic_signature_authorization (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  user_id bigint NOT NULL,
  electronic_signature_enabled tinyint NOT NULL DEFAULT 1,
  authorization_state varchar(32) NOT NULL DEFAULT 'UNAUTHORIZED',
  locked_until timestamp(0) DEFAULT NULL,
  lock_reason varchar(255) DEFAULT NULL,
  last_failure_at timestamp(0) DEFAULT NULL,
  failure_count int NOT NULL DEFAULT 0,
  tenant_id bigint NOT NULL DEFAULT 0,
  create_time timestamp(0) DEFAULT NULL,
  update_time timestamp(0) DEFAULT NULL,
  creator varchar(64) DEFAULT NULL,
  updater varchar(64) DEFAULT NULL,
  deleted tinyint NOT NULL DEFAULT 0,
  CONSTRAINT uk_dcc_esign_authorization_user UNIQUE NULLS DISTINCT (user_id),
  PRIMARY KEY (id)
);

CREATE TABLE erp_kingdee_production_pick_list (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  source_form_id varchar(64) NOT NULL DEFAULT 'PRD_PickMtrl',
  source_fid varchar(64) NOT NULL,
  source_bill_no varchar(128) NOT NULL,
  bill_date timestamp(0) DEFAULT NULL,
  document_status varchar(32) DEFAULT NULL,
  stock_org_number varchar(64) DEFAULT NULL,
  stock_org_name varchar(255) DEFAULT NULL,
  production_org_number varchar(64) DEFAULT NULL,
  production_org_name varchar(255) DEFAULT NULL,
  owner_number varchar(64) DEFAULT NULL,
  owner_name varchar(255) DEFAULT NULL,
  department_number varchar(64) DEFAULT NULL,
  department_name varchar(255) DEFAULT NULL,
  description varchar(512) DEFAULT NULL,
  source_modify_time timestamp(0) DEFAULT NULL,
  last_sync_time timestamp(0) NOT NULL,
  raw_payload character large object DEFAULT NULL,
  creator varchar(64) DEFAULT '',
  create_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updater varchar(64) DEFAULT '',
  update_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted boolean NOT NULL DEFAULT FALSE,
  tenant_id bigint NOT NULL DEFAULT 0,
  CONSTRAINT uk_erp_kingdee_prod_pick_list_source UNIQUE NULLS DISTINCT (tenant_id, source_form_id, source_fid, deleted),
  PRIMARY KEY (id)
);
CREATE INDEX idx_erp_kingdee_prod_pick_list_bill_no ON erp_kingdee_production_pick_list(tenant_id, source_bill_no, deleted);
CREATE INDEX idx_erp_kingdee_prod_pick_list_modify_time ON erp_kingdee_production_pick_list(tenant_id, source_modify_time, deleted);

