);
CREATE INDEX idx_erp_kingdee_prod_pick_list_item_parent ON erp_kingdee_production_pick_list_item(tenant_id, production_pick_list_id, deleted);
CREATE INDEX idx_erp_kingdee_prod_pick_list_item_material ON erp_kingdee_production_pick_list_item(tenant_id, material_number, deleted);
CREATE INDEX idx_erp_kingdee_prod_pick_list_item_mo ON erp_kingdee_production_pick_list_item(tenant_id, production_order_no, deleted);

