CREATE TABLE mes_active_order_handoff_task (
  id BIGINT NOT NULL,
  tenant_id BIGINT NOT NULL,
  active_order_id BIGINT NOT NULL,
  work_order_id BIGINT NOT NULL,
  route_process_id BIGINT NULL,
  task_type VARCHAR(40) NOT NULL,
  source_type VARCHAR(40) NOT NULL,
  source_id BIGINT NOT NULL,
  round_id BIGINT NOT NULL,
  candidate_user_snapshot clob NOT NULL,
  responsibility_snapshot_json clob NOT NULL,
  initiated_by BIGINT NOT NULL,
  notification_only boolean NOT NULL,
  status VARCHAR(16) NOT NULL,
  action_url VARCHAR(1000) NOT NULL,
  reason clob NOT NULL,
  row_version INT NOT NULL DEFAULT 0,
  completed_by BIGINT NULL,
  completion_source_id BIGINT NULL,
  completed_at timestamp(0) NULL,
  due_time timestamp(0) NULL,
  overdue_notified_at timestamp(0) NULL,
  creator VARCHAR(64) NULL,
  updater VARCHAR(64) NULL,
  create_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  update_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted boolean NOT NULL DEFAULT FALSE,
  PRIMARY KEY(id),
  CONSTRAINT uk_mes_handoff_cycle_source UNIQUE NULLS DISTINCT (tenant_id,active_order_id,task_type,source_type,source_id,round_id)
);
CREATE INDEX idx_mes_handoff_cycle_status ON mes_active_order_handoff_task(tenant_id,active_order_id,status);
CREATE INDEX idx_mes_handoff_source ON mes_active_order_handoff_task(tenant_id,source_type,source_id,round_id);

CREATE TABLE mes_pqc_inspection_piece_detail (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  task_id bigint NOT NULL,
  sample_no int NOT NULL,
  item_code varchar(64) NOT NULL,
  item_name varchar(128) NOT NULL,
  inspection_method varchar(512) NOT NULL,
  standard_text varchar(1024) NOT NULL,
  selected_equipment_id bigint NOT NULL,
  selected_equipment_code varchar(64) NOT NULL,
  selected_equipment_name varchar(128) NOT NULL,
  selected_equipment_number varchar(64) NOT NULL,
  standard_lower_limit decimal(18,6) DEFAULT NULL,
  standard_upper_limit decimal(18,6) DEFAULT NULL,
  standard_unit varchar(32) DEFAULT NULL,
  standard_precision int DEFAULT NULL,
  result_type varchar(32) NOT NULL,
  item_result varchar(64) DEFAULT NULL,
  measured_value varchar(128) DEFAULT NULL,
  judgement varchar(32) DEFAULT NULL,
  simulated boolean NOT NULL DEFAULT FALSE,
  simulation_stage varchar(64) DEFAULT NULL,
  simulation_run_id varchar(128) DEFAULT NULL,
  creator varchar(64) DEFAULT '',
  create_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updater varchar(64) DEFAULT '',
  update_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted boolean NOT NULL DEFAULT FALSE,
  tenant_id bigint NOT NULL DEFAULT 0,
  current_sample_no int GENERATED ALWAYS AS (CASE WHEN deleted = FALSE THEN sample_no ELSE NULL END),
  CONSTRAINT uk_mes_pqc_piece_current UNIQUE NULLS DISTINCT (tenant_id, task_id, current_sample_no, item_code),
  PRIMARY KEY (id)
);
CREATE INDEX idx_mes_pqc_piece_task ON mes_pqc_inspection_piece_detail(tenant_id, task_id, sample_no);

CREATE TABLE mes_pqc_inspection_task (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  active_order_id bigint NOT NULL,
  work_order_id bigint NOT NULL,
  route_id bigint NOT NULL,
  route_version_id bigint NOT NULL,
  route_process_id bigint NULL,
  process_id bigint NULL,
  qa_process_id bigint DEFAULT NULL,
  qa_item_code varchar(64) NOT NULL DEFAULT '',
  regulation_version_id bigint NOT NULL,
  inspection_type varchar(32) NOT NULL,
  inspection_rule_key varchar(32) NOT NULL,
  business_date date NOT NULL,
  shift_code varchar(32) NOT NULL,
  round_no int NOT NULL,
  inspection_item_plan_json VARCHAR(8192),
    planned_inspection_quantity int NOT NULL,
  actual_inspection_quantity int NOT NULL DEFAULT 0,
  task_status varchar(32) NOT NULL,
  submitted_content_hash char(64) DEFAULT NULL,
  simulated boolean NOT NULL DEFAULT FALSE,
  simulation_stage varchar(64) DEFAULT NULL,
  simulation_run_id varchar(128) DEFAULT NULL,
  submitted_event_id bigint DEFAULT NULL,
  creator varchar(64) DEFAULT '',
  create_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updater varchar(64) DEFAULT '',
  update_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted boolean NOT NULL DEFAULT FALSE,
  tenant_id bigint NOT NULL DEFAULT 0,
  dcc_project_code_id BIGINT NULL DEFAULT NULL,
  dcc_project_code VARCHAR(64) NULL DEFAULT NULL,
  dcc_project_name VARCHAR(255) NULL DEFAULT NULL,
  qa_regulation_id BIGINT NULL DEFAULT NULL,
  qa_regulation_version_no VARCHAR(32) NULL DEFAULT NULL,
  CONSTRAINT uk_mes_pqc_task_submitted_event UNIQUE NULLS DISTINCT (tenant_id, submitted_event_id, deleted),
  CONSTRAINT uk_mes_pqc_task_process_item_rule_identity UNIQUE NULLS DISTINCT (tenant_id, active_order_id, route_process_id, process_id, regulation_version_id, qa_process_id, qa_item_code, inspection_rule_key, business_date, deleted),
  PRIMARY KEY (id),
