CREATE TABLE system_electronic_signature (
  id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  tenant_id bigint NOT NULL,
  module_code varchar(64) NOT NULL,
  action_code varchar(64) NOT NULL,
  subject_type varchar(64) NOT NULL,
  subject_id varchar(2048) NOT NULL,
  subject_version varchar(128) NOT NULL,
  actor_id bigint NOT NULL,
  meaning_code varchar(64) NOT NULL,
  meaning_label varchar(128) NOT NULL,
  reason varchar(500) NOT NULL,
  signed_at timestamp(0) NOT NULL,
  time_evidence_id varchar(128) NOT NULL,
  authentication_method varchar(64) NOT NULL,
  content_hash char(64) NOT NULL,
  before_content_hash char(64) DEFAULT NULL,
  after_content_hash char(64) DEFAULT NULL,
  canonical_content_json varchar(1000000000) NOT NULL,
  before_content_json varchar(1000000000) DEFAULT NULL,
  after_content_json varchar(1000000000) DEFAULT NULL,
  field_diff_json varchar(1000000000) DEFAULT NULL,
  evidence_hash char(64) NOT NULL,
  algorithm varchar(32) NOT NULL,
  key_version varchar(64) NOT NULL,
  policy_version varchar(64) NOT NULL,
  verification_status varchar(32) NOT NULL,
  idempotency_key varchar(512) NOT NULL,
  command_hash char(64) NOT NULL,
  evidence_format_version varchar(8) NULL,
  command_hash_version varchar(8) NULL,
  process_instance_id varchar(128) DEFAULT NULL,
  task_id varchar(128) DEFAULT NULL,
  node_code varchar(64) DEFAULT NULL,
  node_order int DEFAULT NULL,
  creator varchar(64) DEFAULT '',
  create_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updater varchar(64) DEFAULT '',
  update_time timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted boolean NOT NULL DEFAULT FALSE,
  CONSTRAINT uk_system_esign_idempotency UNIQUE NULLS DISTINCT (tenant_id, idempotency_key_prefix_191, deleted),
  idempotency_key_prefix_191 varchar(191) GENERATED ALWAYS AS (SUBSTRING(idempotency_key, 1, 191)),
  subject_id_prefix_191 varchar(191) GENERATED ALWAYS AS (SUBSTRING(subject_id, 1, 191)),
  PRIMARY KEY (id),
  CONSTRAINT ck_ac02_system_electronic_signature_canonical_content_json_json CHECK (canonical_content_json IS JSON),
  CONSTRAINT ck_ac02_system_electronic_signature_before_content_json_json CHECK (before_content_json IS JSON),
  CONSTRAINT ck_ac02_system_electronic_signature_after_content_json_json CHECK (after_content_json IS JSON),
  CONSTRAINT ck_ac02_system_electronic_signature_field_diff_json_json CHECK (field_diff_json IS JSON)
);
CREATE INDEX idx_system_esign_subject ON system_electronic_signature(tenant_id, module_code, subject_type, subject_id_prefix_191, deleted);
CREATE INDEX idx_system_esign_actor_time ON system_electronic_signature(tenant_id, actor_id, signed_at);

